1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"time"
10	
11		"tidepool/internal/tide"
12	)
13	
14	const usage = `usage: tidepool [-data DIR] <command> [args]
15	
16	commands:
17	  stations                  list known stations
18	  next <station>            the next high and low water
19	  table <station> <date>    hourly heights for a date (YYYY-MM-DD)
20	
21	flags (before or after the command):
22	  -units m|ft               height unit (default m)
23	`
24	
25	var errUsage = errors.New("bad usage")
26	
27	func main() {
28		if err := run(os.Args[1:], os.Stdout, time.Now); err != nil {
29			if errors.Is(err, errUsage) {
30				fmt.Fprint(os.Stderr, usage)
31			} else {
32				fmt.Fprintln(os.Stderr, "tidepool:", err)
33			}
34			os.Exit(1)
35		}
36	}
37	
38	func run(args []string, out io.Writer, now func() time.Time) error {
39		fs := flag.NewFlagSet("tidepool", flag.ContinueOnError)
40		fs.SetOutput(io.Discard)
41		dataDir := fs.String("data", envOr("TIDEPOOL_DATA", "data"), "directory holding stations.csv and constituents.csv")
42		units := fs.String("units", "m", "height unit: m or ft")
43		// Parse repeatedly so flags may follow the command and its arguments.
44		var positional []string
45		for rest := args; ; {
46			if err := fs.Parse(rest); err != nil {
47				return errUsage
48			}
49			if fs.NArg() == 0 {
50				break
51			}
52			positional = append(positional, fs.Arg(0))
53			rest = fs.Args()[1:]
54		}
55		args = positional
56		if len(args) == 0 {
57			return errUsage
58		}
59		unit, err := parseUnit(*units)
60		if err != nil {
61			return err
62		}
63	
64		stations, err := tide.LoadDir(*dataDir)
65		if err != nil {
66			return err
67		}
68	
69		switch args[0] {
70		case "stations":
71			for _, id := range stations.IDs() {
72				st := stations[id]
73				fmt.Fprintf(out, "%-16s %s (%s)\n", id, st.Name, st.Location)
74			}
75			return nil
76	
77		case "next":
78			if len(args) != 2 {
79				return errUsage
80			}
81			st, err := stations.Get(args[1])
82			if err != nil {
83				return err
84			}
85			for _, e := range st.NextExtremes(now(), 2) {
86				fmt.Fprintf(out, "%-4s  %s  %5.2f %s\n", e.Kind, e.Time.In(st.Location).Format("Mon 02 Jan 15:04"), e.Height*unit.factor, unit.name)
87			}
88			return nil
89	
90		case "table":
91			if len(args) != 3 {
92				return errUsage
93			}
94			st, err := stations.Get(args[1])
95			if err != nil {
96				return err
97			}
98			day, err := time.ParseInLocation("2006-01-02", args[2], st.Location)
99			if err != nil {
100				return fmt.Errorf("date %q: want YYYY-MM-DD", args[2])
101			}
102			fmt.Fprintf(out, "%s, %s (heights in %s)\n", st.Name, day.Format("Monday 2 January 2006"), unit.name)
103			// A local day is 23 or 25 hours long when the clocks change. Label rows
104			// with the zone on those days so the repeated hour is distinguishable.
105			hours := int(day.AddDate(0, 0, 1).Sub(day) / time.Hour)
106			layout := "15:04"
107			if hours != 24 {
108				layout = "15:04 MST"
109			}
110			for _, r := range st.Table(day, time.Hour, hours) {
111				fmt.Fprintf(out, "%s  %5.2f %s\n", r.Time.In(st.Location).Format(layout), r.Height*unit.factor, unit.name)
112			}
113			return nil
114		}
115		return errUsage
116	}
117	
118	type heightUnit struct {
119		name   string
120		factor float64 // multiplier from metres
121	}
122	
123	func parseUnit(s string) (heightUnit, error) {
124		switch s {
125		case "m":
126			return heightUnit{"m", 1}, nil
127		case "ft":
128			return heightUnit{"ft", 1 / 0.3048}, nil
129		}
130		return heightUnit{}, fmt.Errorf("units %q: want m or ft", s)
131	}
132	
133	func envOr(key, fallback string) string {
134		if v := os.Getenv(key); v != "" {
135			return v
136		}
137		return fallback
138	}
